static List<object> RepairCuts(){var rows=new List<object>();foreach(object raw in (object[])R["cut_replacements"]){var p=O(raw);int partId=Convert.ToInt32(p["target_part"]);var target=(IZExtrudeFeature)Feature(partId,Convert.ToInt32(p["cut_id"]));var tool=(IZExtrudeFeature)Feature(Convert.ToInt32(p["tool_part"]),Convert.ToInt32(p["tool_feature"]));var cross=target.CrossSection;foreach(object id in (Array)cross.GetCurveIds())cross.DeleteCurve(Convert.ToInt32(id));tool.CrossSection.CopyCurvesTo(cross);var c=(IZSceneElement)cross;var cm=c.GetTransformToParent();cm.MakeIdentity();c.SetTransformToParent(cm);var world=((IZSceneElement)tool.CrossSection).GetTransformToGlobal();var parent=((IZSceneElement)Element(partId)).GetTransformToGlobal();double[] local=new double[16];for(int a=0;a<3;a++){for(int b=0;b<3;b++)local[a*4+b]=Enumerable.Range(0,3).Sum(j=>world.GetValue(a,j)*parent.GetValue(b,j));local[12+a]=Enumerable.Range(0,3).Sum(j=>(world.GetValue(3,j)-parent.GetValue(3,j))*parent.GetValue(a,j));}local[15]=1;var ws=(object[])p["world_shift"];var ps=(object[])p["part_shift"];var coeff=new double[3][];for(int a=0;a<3;a++)coeff[a]=Enumerable.Range(0,Names.Length).Select(k=>Enumerable.Range(0,3).Sum(j=>(N(ws[j])[k]-N(ps[j])[k])*parent.GetValue(a,j))).ToArray();var spec=new Dictionary<string,object>{{"matrix_m",local},{"coefficients",coeff},{"depth",p["depth"]}};BindPose((IZSceneElement)target,spec);target.ExtrudeThroughPart=true;((IZElement)target).Name="RockPro | Wycięcie montażowe L905/915 — kontur HWDrill";rows.Add(new{cut_id=p["cut_id"],target_part=partId,tool_feature=p["tool_feature"],tool_part=p["tool_part"],profile_curves=cross.GetCurvesCount(),local_matrix_m=local,coefficients=coeff});}return rows;}
static void BindPose(IZSceneElement e,Dictionary<string,object> spec){var a=N(spec["matrix_m"]);int depth=Convert.ToInt32(spec["depth"]);var anchor=e.GetAnchorTransform();anchor.MakeIdentity();e.SetAnchorTransform(anchor);e.AnchorBehavior=eZAnchorBehavior.Z_ANCHOR_BEHAVIOR_FIXED_POSITION;Restore(e,a);var coeff=(object[])spec["coefficients"];for(int j=0;j<3;j++)Param(e.ParameterMgr,"RP_Polozenie"+"XYZ"[j],Expr(a[12+j]*1000,N(coeff[j]),depth),"Położenie lokalne powiązane z gabarytami sceny; okucie zachowuje rozmiar katalogowy.");e.ForceSetupParameterExpression();for(int j=0;j<3;j++)e.set_PositionTransformComponentExpression((eZTransformComponentType)j,"RP_Polozenie"+"XYZ"[j]);}
