static Dictionary<string,object> Check(string name,double[] values){var errors=new List<object>();double worstPose=0,worstSize=0;int count=0;foreach(object raw in (object[])R["parts"]){var p=O(raw);int id=Convert.ToInt32(p["id"]);var part=(IZPart)Element(id);var e=(IZSceneElement)part;var m=e.GetTransformToGlobal();var old=N(p["world_matrix_m"]);var shift=(object[])p["shift"];var oldb=N(p["bounds_m"]);var b=N(part.GetBody(true).GetBoundingBox());var growth=(object[])p["local_growth"];double pose=0,size=0;for(int j=0;j<3;j++){var c=N(shift[j]);double expected=old[12+j]*1000+Enumerable.Range(0,Names.Length).Sum(k=>c[k]*(values[k]-Base[k]));pose=Math.Max(pose,Math.Abs(m.GetValue(3,j)*1000-expected));var g=N(growth[j]);double delta=Enumerable.Range(0,Names.Length).Sum(k=>g[k]*(values[k]-Base[k]));size=Math.Max(size,Math.Abs((b[j+3]-b[j])*1000-((oldb[j+3]-oldb[j])*1000+delta)));}for(int k=0;k<12;k++)pose=Math.Max(pose,Math.Abs(m.GetValue(k/4,k%4)-old[k])*1000);worstPose=Math.Max(worstPose,pose);worstSize=Math.Max(worstSize,size);if(pose>.08||size>.08)errors.Add(new{id=id,name=p["name"],pose_error_mm=pose,size_error_mm=size,actual_bounds=b,actual_world=Enumerable.Range(0,16).Select(k=>m.GetValue(k/4,k%4)).ToArray()});count++;}return new Dictionary<string,object>{{"name",name},{"parts_checked",count},{"max_pose_error_mm",worstPose},{"max_size_error_mm",worstSize},{"errors",errors},{"passed",errors.Count==0}};}
