R=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)R["contract"]!="rockpro-tv-parametric-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(R["expected_pid"]))throw new Exception("Wrong source contract or host");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var before=((Array)app.GetAllOpenDocs()).Cast<object>().Select(Doc).ToDictionary(d=>d.FileGUID,d=>d.Modified);
string source=(string)R["source"],output=(string)R["output"];if(Hash(source)!=(string)R["sha256"])throw new Exception("Source hash changed");if(File.Exists(output))throw new Exception("Output exists; refusing overwrite");string copy=Path.Combine(folder,"Hisense_working.ics");File.Copy(source,copy,false);bool already;owned=app.OpenFile2(copy,false,true,out already);if(already){owned=null;throw new Exception("Working copy already open");}S=(IZSceneDoc)owned;S.ConstraintSolver=false;S.NeedConstraintSolve=false;U=(IZSceneDocUtility)S;Names=((object[])R["parameters"]).Select(p=>(string)O(p)["name"]).ToArray();Mark("copy opened");Base=((object[])R["parameters"]).Select(p=>Convert.ToDouble(O(p)["value"])).ToArray();Values(Base);
